67		/**
68		 * #{#cre2b} Criterion 1: Format date as "MMM DD, YYYY"
69		 */
70		formatDate(dateString: string | null | undefined): string {
71			if (!dateString) return 'No Date';
72	
73			try {
74				let year: number, month: number, day: number;
75	
76				if (dateString.includes('T')) {
77					const date = new Date(dateString);
78					year = date.getUTCFullYear();
79					month = date.getUTCMonth();
80					day = date.getUTCDate();
81				} else {
82					const parts = dateString.split('-');
83					year = parseInt(parts[0]);
84					month = parseInt(parts[1]) - 1;
85					day = parseInt(parts[2]);
86				}
87	
88				const dayStr = String(day).padStart(2, '0');
89				return `${MONTHS[month]} ${dayStr}, ${year}`;
90			} catch {
91				return 'No Date';
92			}
93		}
94	
95		/**
96		 * #{#cre2b} Criteria 2, 3, 9: Format amount with $ sign, 2 decimals, comma separators
97		 */
98		formatAmount(amount: number | null | undefined): string {
99			if (amount === null || amount === undefined) return '$0.00';
100			const positive = Math.abs(amount);
101			const fixed = positive.toFixed(2);
102			const [whole, decimal] = fixed.split('.');
103			const withCommas = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
104			return `$${withCommas}.${decimal}`;
105		}
106	
107		/**
108		 * #{#cre2b} Criteria 6, 8: Format vendor name, handle missing
109		 */
110		formatVendorName(name: string | null | undefined): string {
111			if (!name || name.trim() === '') return 'Unknown Vendor';
112			return name.trim();
113		}
