115		/**
116		 * #{#cre2a} Criterion 3: Group expenses by category, sort alphabetically, sort by date within
117		 */
118		groupExpensesByCategory(expenses: Expense[]): Record<string, Expense[]> {
119			const groups: Record<string, Expense[]> = {};
120	
121			for (const expense of expenses) {
122				const categoryName = expense.category_name || 'Uncategorized';
123				if (!groups[categoryName]) {
124					groups[categoryName] = [];
125				}
126				groups[categoryName].push(expense);
127			}
128	
129			// Sort within each group by date ascending
130			for (const key of Object.keys(groups)) {
131				groups[key].sort((a, b) => {
132					const dateA = a.transaction_date || '';
133					const dateB = b.transaction_date || '';
134					return dateA.localeCompare(dateB);
135				});
136			}
137	
138			// Return as ordered object (alphabetical keys)
139			const sorted: Record<string, Expense[]> = {};
