219		/**
220		 * #{#cre3b} Criterion 7, 8: Trigger browser download
221		 */
222		downloadPDF(pdfBytes: Uint8Array, filename: string): void {
223			// Copy into a fresh Uint8Array so the backing buffer is a plain ArrayBuffer,
224			// which is what BlobPart requires (pdf-lib bytes are typed over ArrayBufferLike).
225			const blob = new Blob([new Uint8Array(pdfBytes)], { type: 'application/pdf' });
226			const link = document.createElement('a');
227			const url = URL.createObjectURL(blob);
228			link.setAttribute('href', url);
229			link.setAttribute('download', filename);
230			link.style.visibility = 'hidden';
231			document.body.appendChild(link);
232			link.click();
233			document.body.removeChild(link);
234			URL.revokeObjectURL(url);
235		}
