546		/** Scale the image to fit the remaining page area (never upscale) and centre it horizontally */
547		private drawScaledImage(cursor: PageCursor, image: PDFImage): void {
548			const maxHeight = cursor.y - MARGIN;
549			const scale = Math.min(CONTENT_WIDTH / image.width, maxHeight / image.height, 1);
550			const width = image.width * scale;
551			const height = image.height * scale;
552			const x = MARGIN + (CONTENT_WIDTH - width) / 2;
553	
554			cursor.page.drawImage(image, {
555				x,
556				y: cursor.y - height,
557				width,
558				height
559			});
560		}
