563	
564		private drawText(
565			page: PDFPage,
566			text: string,
567			font: PDFFont,
568			size: number,
569			x: number,
570			y: number
571		): number {
572			page.drawText(text, { x, y, size, font, color: rgb(0, 0, 0) });
573			return y - size - 2;
574		}
575	
576		private drawWrappedText(
577			page: PDFPage,
578			text: string,
579			font: PDFFont,
580			size: number,
581			x: number,
582			y: number,
583			maxWidth: number
584		): number {
585			const words = text.split(' ');
586			let line = '';
587			const lineHeight = size + 2;
588	
589			for (const word of words) {
590				const testLine = line ? `${line} ${word}` : word;
591				const testWidth = font.widthOfTextAtSize(testLine, size);
592				if (testWidth > maxWidth && line) {
593					page.drawText(line, { x, y, size, font, color: rgb(0, 0, 0) });
594					y -= lineHeight;
595					line = word;
596				} else {
597					line = testLine;
598				}
599			}
600			if (line) {
601				page.drawText(line, { x, y, size, font, color: rgb(0, 0, 0) });
602				y -= lineHeight;
603			}
604			return y;
605		}
606	
607		private drawTextRight(
608			page: PDFPage,
609			text: string,
610			font: PDFFont,
611			size: number,
612			rightX: number,
613			y: number
614		): number {
615			const width = font.widthOfTextAtSize(text, size);
616			page.drawText(text, { x: rightX - width, y, size, font, color: rgb(0, 0, 0) });
617			return y - size - 2;
618		}
619	
620		private truncateText(text: string, font: PDFFont, size: number, maxWidth: number): string {
621			if (font.widthOfTextAtSize(text, size) <= maxWidth) return text;
622			const ellipsis = '...';
623			let truncated = text;
624			while (truncated.length > 0 && font.widthOfTextAtSize(truncated + ellipsis, size) > maxWidth) {
625				truncated = truncated.slice(0, -1);
626			}
627			return truncated + ellipsis;
628		}
