630		private async embedImage(pdfDoc: PDFDocument, imageBytes: Uint8Array): Promise<PDFImage | null> {
631			// Try JPEG first, then PNG
632			try {
633				return await pdfDoc.embedJpg(imageBytes);
634			} catch {
635				try {
636					return await pdfDoc.embedPng(imageBytes);
637				} catch {
638					return null;
639				}
640			}
641		}
642	}
