/**
 * resolveCategory
 *
 * Single shared way to answer "which Category does this row belong to?"
 * (RF-09 — replaces three divergent implementations: the expenses page's
 * inline Category rebuild, its `categories.find(...)` lookup, and the
 * receipts/reconciliation pages' hand-rolled categoryMap loops.)
 *
 * Rows carry denormalized category fields (`category_id` / `category_name` /
 * `category_color`) produced by ExpenseService. Resolution prefers the
 * authoritative entry in the loaded `categories` list, falling back to the
 * row's denormalized fields when the list has no match (e.g. category loaded
 * on the row before the categories list refreshed).
 */

import type { Category } from '$lib/types/Category';

/** Minimal row shape: anything carrying a denormalized category reference. */
export interface CategoryRowRef {
	category_id?: string | null;
	category_name?: string | null;
	category_color?: string | null;
}

/**
 * Resolve a row's Category, or null when the row is uncategorized.
 */
export function resolveCategory(row: CategoryRowRef, categories: Category[]): Category | null {
	if (!row.category_id) return null;

	const match = categories.find((c) => c.id === row.category_id);
	if (match) return match;

	if (!row.category_name) return null;

	return {
		id: row.category_id,
		name: row.category_name,
		color: row.category_color ?? null
	};
}

/**
 * Build a receipt-id → Category map for pages that render many rows
 * (receipts / reconciliation). Uncategorized rows map to null.
 */
export function buildCategoryMap<Row extends CategoryRowRef & { receipt_id: string }>(
	rows: Row[],
	categories: Category[]
): Record<string, Category | null> {
	const map: Record<string, Category | null> = {};
	for (const row of rows) {
		map[row.receipt_id] = resolveCategory(row, categories);
	}
	return map;
}

/**
 * resolveCategory unit tests (RF-09)
 *
 * Covers the single shared category-resolution helper used by the
 * expenses and receipts pages (and adoptable by reconciliation).
 */

import { describe, it, expect } from 'vitest';
import { resolveCategory, buildCategoryMap, type CategoryRowRef } from './resolveCategory';
import type { Category } from '$lib/types/Category';

const groceries: Category = { id: 'cat-1', name: 'Groceries', color: '#10B981', family_id: 'f1' };
const noColor: Category = { id: 'cat-2', name: 'Misc', color: null, family_id: 'f1' };
const categories: Category[] = [groceries, noColor];

describe('resolveCategory', () => {
	it('returns null for an uncategorized row (category_id null)', () => {
		const row: CategoryRowRef = { category_id: null, category_name: null, category_color: null };
		expect(resolveCategory(row, categories)).toBeNull();
	});

	it('returns null when category_id is undefined (row shape without category fields)', () => {
		expect(resolveCategory({}, categories)).toBeNull();
	});

	it('prefers the authoritative entry from the categories list', () => {
		const row: CategoryRowRef = {
			category_id: 'cat-1',
			category_name: 'Stale Name',
			category_color: '#000000'
		};
		expect(resolveCategory(row, categories)).toBe(groceries);
	});

	it('resolves a category whose stored color is null', () => {
		const row: CategoryRowRef = { category_id: 'cat-2' };
		expect(resolveCategory(row, categories)).toBe(noColor);
	});

	it('falls back to the denormalized row fields when the list has no match', () => {
		const row: CategoryRowRef = {
			category_id: 'cat-99',
			category_name: 'Deleted Category',
			category_color: '#FF0000'
		};
		expect(resolveCategory(row, categories)).toEqual({
			id: 'cat-99',
			name: 'Deleted Category',
			color: '#FF0000'
		});
	});

	it('fallback keeps color null when the row has no category_color', () => {
		const row: CategoryRowRef = { category_id: 'cat-99', category_name: 'Deleted Category' };
		expect(resolveCategory(row, categories)).toEqual({
			id: 'cat-99',
			name: 'Deleted Category',
			color: null
		});
	});

	it('returns null when the id is unknown and no denormalized name exists', () => {
		const row: CategoryRowRef = { category_id: 'cat-99', category_name: null };
		expect(resolveCategory(row, categories)).toBeNull();
	});

	it('resolves against an empty categories list via the denormalized fields', () => {
		const row: CategoryRowRef = {
			category_id: 'cat-1',
			category_name: 'Groceries',
			category_color: '#10B981'
		};
		expect(resolveCategory(row, [])).toEqual({
			id: 'cat-1',
			name: 'Groceries',
			color: '#10B981'
		});
	});
});

describe('buildCategoryMap', () => {
	it('maps each receipt_id to its resolved category', () => {
		const rows = [
			{ receipt_id: 'r1', category_id: 'cat-1' },
			{ receipt_id: 'r2', category_id: null },
			{ receipt_id: 'r3', category_id: 'cat-2' }
		];
		expect(buildCategoryMap(rows, categories)).toEqual({
			r1: groceries,
			r2: null,
			r3: noColor
		});
	});

	it('returns an empty map for no rows', () => {
		expect(buildCategoryMap([], categories)).toEqual({});
	});
});

/**
 * PDF export button state (RF-13)
 *
 * #{#cre1a} #{#cre1b} #{#cre4a} Button enable/disable logic.
 * Pure UI-state predicate, moved out of PDFExportService (it was a static
 * parked on the service). The expenses page feeds it via a $derived.
 */

export interface PDFExportUIState {
	filteredExpensesCount: number;
	selectedCategoryIds: string[];
	showUncategorizedOnly: boolean;
	isExporting: boolean;
}

export function shouldEnablePDFExport(state: PDFExportUIState): boolean {
	if (state.isExporting) return false;
	if (state.filteredExpensesCount === 0) return false;
	if (state.selectedCategoryIds.length === 0) return false;
	if (state.showUncategorizedOnly) return false;
	return true;
}

/**
 * shouldEnablePDFExport tests (RF-13)
 *
 * Moved from PDFExportService.spec.ts alongside the predicate's new home.
 * #{#cre1a} #{#cre1b} #{#cre4a} Button Enable/Disable Logic.
 */

import { describe, it, expect } from 'vitest';
import { shouldEnablePDFExport } from './pdfExportState';

describe('shouldEnablePDFExport', () => {
	it('should return true when there are expenses and a category filter is active', () => {
		// #{#cre1a} Criterion 3, 4 / #{#cre1b} Criterion 1
		const result = shouldEnablePDFExport({
			filteredExpensesCount: 5,
			selectedCategoryIds: ['cat1'],
			showUncategorizedOnly: false,
			isExporting: false
		});
		expect(result).toBe(true);
	});

	it('should return false when there are no expenses', () => {
		// #{#cre1a} Criterion 3
		const result = shouldEnablePDFExport({
			filteredExpensesCount: 0,
			selectedCategoryIds: ['cat1'],
			showUncategorizedOnly: false,
			isExporting: false
		});
		expect(result).toBe(false);
	});

	it('should return false when no category filter is active', () => {
		// #{#cre1a} Criterion 4
		const result = shouldEnablePDFExport({
			filteredExpensesCount: 5,
			selectedCategoryIds: [],
			showUncategorizedOnly: false,
			isExporting: false
		});
		expect(result).toBe(false);
	});

	it('should return false when uncategorized-only toggle is active', () => {
		// #{#cre1b} Criterion 5
		const result = shouldEnablePDFExport({
			filteredExpensesCount: 5,
			selectedCategoryIds: ['cat1'],
			showUncategorizedOnly: true,
			isExporting: false
		});
		expect(result).toBe(false);
	});

	it('should return false when already exporting', () => {
		// #{#cre4a} Criterion 1
		const result = shouldEnablePDFExport({
			filteredExpensesCount: 5,
			selectedCategoryIds: ['cat1'],
			showUncategorizedOnly: false,
			isExporting: true
		});
		expect(result).toBe(false);
	});
});

